    {
        return ! $this->dataSource;
    }

    public function getDataSource(): ?Closure
    {
        return $this->dataSource;
    }

    public function getResolveSelectedRecordsCallback(): ?Closure
    {
        return $this->resolveSelectedRecordsUsing;
    }

